<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/admin-auth.php'; $pdo=getPDO(); requireAdminLogin(); if(isset($_GET['delete'])){$s=$pdo->prepare('DELETE FROM reviews WHERE id=?');$s->execute([(int)$_GET['delete']]);header('Location: reviews.php');exit;} $rows=$pdo->query('SELECT r.*,c.name FROM reviews r JOIN customers c ON c.id=r.customer_id ORDER BY r.created_at DESC')->fetchAll(); ?><!doctype html><html><head><title>Reviews</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'partials/sidebar.php'; ?><main class="section"><div class="container"><h1>Review Management</h1><table class="admin-table"><tr><th>Customer</th><th>Rating</th><th>Review</th><th>Date</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><?php echo htmlspecialchars($r['name']); ?></td><td><?php echo str_repeat('★',(int)$r['rating']); ?></td><td><?php echo htmlspecialchars($r['review_text']); ?></td><td><?php echo $r['created_at']; ?></td><td><a class="btn btn-small btn-secondary" onclick="return confirm('Delete review?')" href="?delete=<?php echo $r['id']; ?>">Delete</a></td></tr><?php endforeach; ?></table></div></main></body></html>
